// Release builds sign with the Moocon upload key when its Gradle properties are set
// (MOOCON_RELEASE_STORE_FILE, _STORE_PASSWORD, _KEY_ALIAS, _KEY_PASSWORD, kept in ~/.gradle/gradle.properties,
// never in the repo). Without them a release build falls back to the debug key, so dev builds are unaffected.
// android/ is regenerated by prebuild, so this has to be a config plugin rather than an edit to build.gradle.
const { withAppBuildGradle } = require('expo/config-plugins')

const RELEASE_SIGNING = `
        release {
            if (project.findProperty('MOOCON_RELEASE_STORE_FILE')) {
                storeFile file(project.findProperty('MOOCON_RELEASE_STORE_FILE'))
                storePassword project.findProperty('MOOCON_RELEASE_STORE_PASSWORD')
                keyAlias project.findProperty('MOOCON_RELEASE_KEY_ALIAS')
                keyPassword project.findProperty('MOOCON_RELEASE_KEY_PASSWORD')
            }
        }`

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let gradle = cfg.modResults.contents
    if (gradle.includes('MOOCON_RELEASE_STORE_FILE')) return cfg

    const signingConfigs = /signingConfigs \{\n/
    // Anchored on buildTypes: the release signingConfig inserted below also opens with `release {`.
    const releaseBuildType = /(buildTypes \{[\s\S]*?\brelease \{[\s\S]*?)signingConfig signingConfigs\.debug/
    if (!signingConfigs.test(gradle) || !releaseBuildType.test(gradle)) {
      throw new Error('with-release-signing: build.gradle layout changed; update the plugin')
    }
    gradle = gradle.replace(
      releaseBuildType,
      "$1signingConfig project.findProperty('MOOCON_RELEASE_STORE_FILE') ? signingConfigs.release : signingConfigs.debug",
    )
    gradle = gradle.replace(signingConfigs, (m) => `${m}${RELEASE_SIGNING.slice(1)}\n`)
    cfg.modResults.contents = gradle
    return cfg
  })
}
